00057 // when we ask cxxopts to use Unicode, help strings are processed using ICU,
00058 // which results in the correct lengths being computed for strings when they
00059 // are formatted for the help output
00060 // it is necessary to make sure that <unicode/unistr.h> can be found by the
00061 // compiler, and that icu-uc is linked in to the binary.
00062 
00063 #ifdef CXXOPTS_USE_UNICODE
00064 #include <unicode/unistr.h>
00065 
00066 namespace cxxopts {
00067 typedef icu::UnicodeString String;
00068 
00069 inline String toLocalString(std::string s) { return icu::UnicodeString::fromUTF8(std::move(s)); }
00070 
00071 class UnicodeStringIterator : public std::iterator<std::forward_iterator_tag, int32_t> {
00072 public:
00073     UnicodeStringIterator(const icu::UnicodeString *string, int32_t pos) : s(string), i(pos) {}
00074 
00075     value_type operator*() const { return s->char32At(i); }
00076 
00077     bool operator==(const UnicodeStringIterator &rhs) const { return s == rhs.s && i == rhs.i; }
00078 
00079     bool operator!=(const UnicodeStringIterator &rhs) const { return !(*this == rhs); }
00080 
00081     UnicodeStringIterator &operator++() {
00082         ++i;
00083         return *this;
00084     }
00085 
00086     UnicodeStringIterator operator+(int32_t v) { return UnicodeStringIterator(s, i + v); }
00087 
00088 private:
00089     const icu::UnicodeString *s;
00090     int32_t i;
00091 };
