00268 namespace {
00269 std::basic_regex<char> integer_pattern("(-)?(0x)?([0-9a-zA-Z]+)|((0x)?0)");
00270 std::basic_regex<char> truthy_pattern("(t|T)((rue)|(RUE))?");
00271 std::basic_regex<char> falsy_pattern("((f|F)((alse)|(ALSE?)))?");
00272 } // namespace
00273 
00274 namespace detail {
00275 template <typename T, bool B> struct SignedCheck;
00276 
00277 template <typename T> struct SignedCheck<T, true> {
00278     template <typename U> void operator()(bool negative, U u, const std::string &text) {
00279         if (negative) {
00280             if (u > static_cast<U>(-std::numeric_limits<T>::min())) {
00281                 throw argument_incorrect_type(text);
00282             }
00283         } else {
00284             if (u > static_cast<U>(std::numeric_limits<T>::max())) {
00285                 throw argument_incorrect_type(text);
00286             }
00287         }
00288     }
00289 };
00290 
00291 template <typename T> struct SignedCheck<T, false> {
00292     template <typename U> void operator()(bool, U, const std::string &) {}
00293 };
00294 
00295 template <typename T, typename U> void check_signed_range(bool negative, U value, const std::string &text) {
00296     SignedCheck<T, std::numeric_limits<T>::is_signed>()(negative, value, text);
00297 }
00298 } // namespace detail
00299 
00300 template <typename R, typename T> R checked_negate(T &&t, const std::string &, std::true_type) {
00301     // if we got to here, then `t` is a positive number that fits into
00302     // `R`. So to avoid MSVC C4146, we first cast it to `R`.
00303     // See https://github.com/jarro2783/cxxopts/issues/62 for more details.
00304     return -static_cast<R>(t);
00305 }
00306 
00307 template <typename R, typename T> T checked_negate(T &&, const std::string &text, std::false_type) {
00308     throw argument_incorrect_type(text);
00309 }
00310 
00311 template <typename T> void integer_parser(const std::string &text, T &value) {
00312     std::smatch match;
00313     std::regex_match(text, match, integer_pattern);
00314 
00315     if (match.length() == 0) {
00316         throw argument_incorrect_type(text);
00317     }
00318 
00319     if (match.length(4) > 0) {
00320         value = 0;
00321         return;
00322     }
00323 
00324     using US = typename std::make_unsigned<T>::type;
00325 
00326     constexpr auto umax = std::numeric_limits<US>::max();
00327     constexpr bool is_signed = std::numeric_limits<T>::is_signed;
00328     const bool negative = match.length(1) > 0;
00329     const uint8_t base = match.length(2) > 0 ? 16 : 10;
00330 
00331     auto value_match = match[3];
00332 
00333     US result = 0;
00334 
00335     for (auto iter = value_match.first; iter != value_match.second; ++iter) {
00336         US digit = 0;
00337 
00338         if (*iter >= '0' && *iter <= '9') {
00339             digit = *iter - '0';
00340         } else if (base == 16 && *iter >= 'a' && *iter <= 'f') {
00341             digit = *iter - 'a' + 10;
00342         } else if (base == 16 && *iter >= 'A' && *iter <= 'F') {
00343             digit = *iter - 'A' + 10;
00344         } else {
00345             throw argument_incorrect_type(text);
00346         }
00347 
00348         if (umax - digit < result * base) {
00349             throw argument_incorrect_type(text);
00350         }
00351 
00352         result = result * base + digit;
00353     }
00354 
00355     detail::check_signed_range<T>(negative, result, text);
00356 
00357     if (negative) {
00358         value = checked_negate<T>(result, text, std::integral_constant<bool, is_signed>());
00359     } else {
00360         value = result;
00361     }
00362 }
00363 
00364 template <typename T> void stringstream_parser(const std::string &text, T &value) {
00365     std::stringstream in(text);
00366     in >> value;
00367     if (!in) {
00368         throw argument_incorrect_type(text);
00369     }
00370 }
00371 
00372 inline void parse_value(const std::string &text, uint8_t &value) { integer_parser(text, value); }
00373 
00374 inline void parse_value(const std::string &text, int8_t &value) { integer_parser(text, value); }
00375 
00376 inline void parse_value(const std::string &text, uint16_t &value) { integer_parser(text, value); }
00377 
00378 inline void parse_value(const std::string &text, int16_t &value) { integer_parser(text, value); }
00379 
00380 inline void parse_value(const std::string &text, uint32_t &value) { integer_parser(text, value); }
00381 
00382 inline void parse_value(const std::string &text, int32_t &value) { integer_parser(text, value); }
00383 
00384 inline void parse_value(const std::string &text, uint64_t &value) { integer_parser(text, value); }
00385 
00386 inline void parse_value(const std::string &text, int64_t &value) { integer_parser(text, value); }
00387 
00388 inline void parse_value(const std::string &text, bool &value) {
00389     std::smatch result;
00390     std::regex_match(text, result, truthy_pattern);
00391 
00392     if (!result.empty()) {
00393         value = true;
00394         return;
00395     }
00396 
00397     std::regex_match(text, result, falsy_pattern);
00398     if (!result.empty()) {
00399         value = false;
00400         return;
00401     }
00402 
00403     throw argument_incorrect_type(text);
00404 }
00405 
00406 inline void parse_value(const std::string &text, std::string &value) { value = text; }
00407 
00408 // The fallback parser. It uses the stringstream parser to parse all types
00409 // that have not been overloaded explicitly.  It has to be placed in the
00410 // source code before all other more specialized templates.
00411 template <typename T> void parse_value(const std::string &text, T &value) { stringstream_parser(text, value); }
00412 
00413 template <typename T> void parse_value(const std::string &text, std::vector<T> &value) {
00414     T v;
00415     parse_value(text, v);
00416     value.push_back(v);
00417 }
00418 
00419 #ifdef CXXOPTS_HAS_OPTIONAL
00420 template <typename T> void parse_value(const std::string &text, std::optional<T> &value) {
00421     T result;
00422     parse_value(text, result);
00423     value = std::move(result);
00424 }
00425 #endif
