00431 template <typename T> class abstract_value : public Value {
00432     using Self = abstract_value<T>;
00433 
00434 public:
00435     abstract_value() : m_result(std::make_shared<T>()), m_store(m_result.get()) {}
00436 
00437     abstract_value(T *t) : m_store(t) {}
00438 
00439     virtual ~abstract_value() = default;
00440 
00441     abstract_value(const abstract_value &rhs) {
00442         if (rhs.m_result) {
00443             m_result = std::make_shared<T>();
00444             m_store = m_result.get();
00445         } else {
00446             m_store = rhs.m_store;
00447         }
00448 
00449         m_default = rhs.m_default;
00450         m_implicit = rhs.m_implicit;
00451         m_default_value = rhs.m_default_value;
00452         m_implicit_value = rhs.m_implicit_value;
00453     }
00454 
00455     void parse(const std::string &text) const { parse_value(text, *m_store); }
00456 
00457     bool is_container() const { return type_is_container<T>::value; }
00458 
00459     void parse() const { parse_value(m_default_value, *m_store); }
00460 
00461     bool has_default() const { return m_default; }
00462 
00463     bool has_implicit() const { return m_implicit; }
00464 
00465     std::shared_ptr<Value> default_value(const std::string &value) {
00466         m_default = true;
00467         m_default_value = value;
00468         return shared_from_this();
00469     }
00470 
00471     std::shared_ptr<Value> implicit_value(const std::string &value) {
00472         m_implicit = true;
00473         m_implicit_value = value;
00474         return shared_from_this();
00475     }
00476 
00477     std::string get_default_value() const { return m_default_value; }
00478 
00479     std::string get_implicit_value() const { return m_implicit_value; }
00480 
00481     bool is_boolean() const { return std::is_same<T, bool>::value; }
00482 
00483     const T &get() const {
00484         if (m_store == nullptr) {
00485             return *m_result;
00486         } else {
00487             return *m_store;
00488         }
00489     }
00490 
00491 protected:
00492     std::shared_ptr<T> m_result;
00493     T *m_store;
00494 
00495     bool m_default = false;
00496     bool m_implicit = false;
00497 
00498     std::string m_default_value;
00499     std::string m_implicit_value;
00500 };
