00581 class OptionValue {
00582 public:
00583     void parse(std::shared_ptr<const OptionDetails> details, const std::string &text) {
00584         ensure_value(details);
00585         ++m_count;
00586         m_value->parse(text);
00587     }
00588 
00589     void parse_default(std::shared_ptr<const OptionDetails> details) {
00590         ensure_value(details);
00591         m_value->parse();
00592     }
00593 
00594     size_t count() const { return m_count; }
00595 
00596     template <typename T> const T &as() const {
00597 #ifdef CXXOPTS_NO_RTTI
00598         return static_cast<const values::standard_value<T> &>(*m_value).get();
00599 #else
00600         return dynamic_cast<const values::standard_value<T> &>(*m_value).get();
00601 #endif
00602     }
00603 
00604 private:
00605     void ensure_value(std::shared_ptr<const OptionDetails> details) {
00606         if (m_value == nullptr) {
00607             m_value = details->make_storage();
00608         }
00609     }
00610 
00611     std::shared_ptr<Value> m_value;
00612     size_t m_count = 0;
00613 };
