00634 class ParseResult {
00635 public:
00636     ParseResult(const std::unordered_map<std::string, std::shared_ptr<OptionDetails>> &, std::vector<std::string>,
00637                 bool allow_unrecognised, int &, char **&);
00638 
00639     size_t count(const std::string &o) const {
00640         auto iter = m_options.find(o);
00641         if (iter == m_options.end()) {
00642             return 0;
00643         }
00644 
00645         auto riter = m_results.find(iter->second);
00646 
00647         return riter->second.count();
00648     }
00649 
00650     const OptionValue &operator[](const std::string &option) const {
00651         auto iter = m_options.find(option);
00652 
00653         if (iter == m_options.end()) {
00654             throw option_not_present_exception(option);
00655         }
00656 
00657         auto riter = m_results.find(iter->second);
00658 
00659         return riter->second;
00660     }
00661 
00662     const std::vector<KeyValue> &arguments() const { return m_sequential; }
00663 
00664 private:
00665     OptionValue &get_option(std::shared_ptr<OptionDetails>);
00666 
00667     void parse(int &argc, char **&argv);
00668 
00669     void add_to_option(const std::string &option, const std::string &arg);
00670 
00671     bool consume_positional(std::string a);
00672 
00673     void parse_option(std::shared_ptr<OptionDetails> value, const std::string &name, const std::string &arg = "");
00674 
00675     void parse_default(std::shared_ptr<OptionDetails> details);
00676 
00677     void checked_parse_arg(int argc, char *argv[], int &current, std::shared_ptr<OptionDetails> value, const std::string &name);
00678 
00679     const std::unordered_map<std::string, std::shared_ptr<OptionDetails>> &m_options;
00680     std::vector<std::string> m_positional;
00681     std::vector<std::string>::iterator m_next_positional;
00682     std::unordered_set<std::string> m_positional_set;
00683     std::unordered_map<std::shared_ptr<OptionDetails>, OptionValue> m_results;
00684 
00685     bool m_allow_unrecognised;
00686 
00687     std::vector<KeyValue> m_sequential;
00688 };
