00774 namespace {
00775 constexpr int OPTION_LONGEST = 50;
00776 constexpr int OPTION_DESC_GAP = 2;
00777 
00778 std::basic_regex<char> option_matcher("--([[:alnum:]][-_[:alnum:]]+)(=(.*))?|-([[:alnum:]]+)");
00779 
00780 std::basic_regex<char> option_specifier("(([[:alnum:]]),)?[ ]*([[:alnum:]][-_[:alnum:]]*)?");
00781 
00782 String format_option(const HelpOptionDetails &o) {
00783     auto &s = o.s;
00784     auto &l = o.l;
00785 
00786     String result = "  ";
00787 
00788     if (s.size() > 0) {
00789         result += "-" + toLocalString(s) + ",";
00790     } else {
00791         result += "   ";
00792     }
00793 
00794     if (l.size() > 0) {
00795         result += " --" + toLocalString(l);
00796     }
00797 
00798     auto arg = o.arg_help.size() > 0 ? toLocalString(o.arg_help) : "arg";
00799 
00800     if (!o.is_boolean) {
00801         if (o.has_implicit) {
00802             result += " [=" + arg + "(=" + toLocalString(o.implicit_value) + ")]";
00803         } else {
00804             result += " " + arg;
00805         }
00806     }
00807 
00808     return result;
00809 }
00810 
00811 String format_description(const HelpOptionDetails &o, size_t start, size_t width) {
00812     auto desc = o.desc;
00813 
00814     if (o.has_default && (!o.is_boolean || o.default_value != "false")) {
00815         desc += toLocalString(" (default: " + o.default_value + ")");
00816     }
00817 
00818     String result;
00819 
00820     auto current = std::begin(desc);
00821     auto startLine = current;
00822     auto lastSpace = current;
00823 
00824     auto size = size_t{};
00825 
00826     while (current != std::end(desc)) {
00827         if (*current == ' ') {
00828             lastSpace = current;
00829         }
00830 
00831         if (size > width) {
00832             if (lastSpace == startLine) {
00833                 stringAppend(result, startLine, current + 1);
00834                 stringAppend(result, "\n");
00835                 stringAppend(result, start, ' ');
00836                 startLine = current + 1;
00837                 lastSpace = startLine;
00838             } else {
00839                 stringAppend(result, startLine, lastSpace);
00840                 stringAppend(result, "\n");
00841                 stringAppend(result, start, ' ');
00842                 startLine = lastSpace + 1;
00843             }
00844             size = 0;
00845         } else {
00846             ++size;
00847         }
00848 
00849         ++current;
00850     }
00851 
00852     // append whatever is left
00853     stringAppend(result, startLine, current);
00854 
00855     return result;
00856 }
00857 } // namespace
00858 
00859 inline ParseResult::ParseResult(const std::unordered_map<std::string, std::shared_ptr<OptionDetails>> &options,
00860                                 std::vector<std::string> positional, bool allow_unrecognised, int &argc, char **&argv)
00861     : m_options(options), m_positional(std::move(positional)), m_next_positional(m_positional.begin()),
00862       m_allow_unrecognised(allow_unrecognised) {
00863     parse(argc, argv);
00864 }
00865 
00866 inline OptionAdder Options::add_options(std::string group) { return OptionAdder(*this, std::move(group)); }
00867 
00868 inline OptionAdder &OptionAdder::operator()(const std::string &opts, const std::string &desc, std::shared_ptr<const Value> value,
00869                                             std::string arg_help) {
00870     std::match_results<const char *> result;
00871     std::regex_match(opts.c_str(), result, option_specifier);
00872 
00873     if (result.empty()) {
00874         throw invalid_option_format_error(opts);
00875     }
00876 
00877     const auto &short_match = result[2];
00878     const auto &long_match = result[3];
00879 
00880     if (!short_match.length() && !long_match.length()) {
00881         throw invalid_option_format_error(opts);
00882     } else if (long_match.length() == 1 && short_match.length()) {
00883         throw invalid_option_format_error(opts);
00884     }
00885 
00886     auto option_names = [](const std::sub_match<const char *> &short_, const std::sub_match<const char *> &long_) {
00887         if (long_.length() == 1) {
00888             return std::make_tuple(long_.str(), short_.str());
00889         } else {
00890             return std::make_tuple(short_.str(), long_.str());
00891         }
00892     }(short_match, long_match);
00893 
00894     m_options.add_option(m_group, std::get<0>(option_names), std::get<1>(option_names), desc, value, std::move(arg_help));
00895 
00896     return *this;
00897 }
00898 
00899 inline void ParseResult::parse_default(std::shared_ptr<OptionDetails> details) { m_results[details].parse_default(details); }
00900 
00901 inline void ParseResult::parse_option(std::shared_ptr<OptionDetails> value, const std::string & /*name*/, const std::string &arg) {
00902     auto &result = m_results[value];
00903     result.parse(value, arg);
00904 
00905     m_sequential.emplace_back(value->long_name(), arg);
00906 }
