00908 inline void ParseResult::checked_parse_arg(int argc, char *argv[], int &current, std::shared_ptr<OptionDetails> value,
00909                                            const std::string &name) {
00910     if (current + 1 >= argc) {
00911         if (value->value().has_implicit()) {
00912             parse_option(value, name, value->value().get_implicit_value());
00913         } else {
00914             throw missing_argument_exception(name);
00915         }
00916     } else {
00917         if (value->value().has_implicit()) {
00918             parse_option(value, name, value->value().get_implicit_value());
00919         } else {
00920             parse_option(value, name, argv[current + 1]);
00921             ++current;
00922         }
00923     }
00924 }
00925 
00926 inline void ParseResult::add_to_option(const std::string &option, const std::string &arg) {
00927     auto iter = m_options.find(option);
00928 
00929     if (iter == m_options.end()) {
00930         throw option_not_exists_exception(option);
00931     }
00932 
00933     parse_option(iter->second, option, arg);
00934 }
00935 
00936 inline bool ParseResult::consume_positional(std::string a) {
00937     while (m_next_positional != m_positional.end()) {
00938         auto iter = m_options.find(*m_next_positional);
00939         if (iter != m_options.end()) {
00940             auto &result = m_results[iter->second];
00941             if (!iter->second->value().is_container()) {
00942                 if (result.count() == 0) {
00943                     add_to_option(*m_next_positional, a);
00944                     ++m_next_positional;
00945                     return true;
00946                 } else {
00947                     ++m_next_positional;
00948                     continue;
00949                 }
00950             } else {
00951                 add_to_option(*m_next_positional, a);
00952                 return true;
00953             }
00954         }
00955         ++m_next_positional;
00956     }
00957 
00958     return false;
00959 }
00960 
00961 inline void Options::parse_positional(std::string option) { parse_positional(std::vector<std::string>{std::move(option)}); }
00962 
00963 inline void Options::parse_positional(std::vector<std::string> options) {
00964     m_positional = std::move(options);
00965     m_next_positional = m_positional.begin();
00966 
00967     m_positional_set.insert(m_positional.begin(), m_positional.end());
00968 }
00969 
00970 inline void Options::parse_positional(std::initializer_list<std::string> options) {
00971     parse_positional(std::vector<std::string>(std::move(options)));
00972 }
