00974 inline ParseResult Options::parse(int &argc, char **&argv) {
00975     ParseResult result(m_options, m_positional, m_allow_unrecognised, argc, argv);
00976     return result;
00977 }
00978 
00979 inline void ParseResult::parse(int &argc, char **&argv) {
00980     int current = 1;
00981 
00982     int nextKeep = 1;
00983 
00984     bool consume_remaining = false;
00985 
00986     while (current != argc) {
00987         if (strcmp(argv[current], "--") == 0) {
00988             consume_remaining = true;
00989             ++current;
00990             break;
00991         }
00992 
00993         std::match_results<const char *> result;
00994         std::regex_match(argv[current], result, option_matcher);
00995 
00996         if (result.empty()) {
00997             // not a flag
00998 
00999             // if true is returned here then it was consumed, otherwise it is
01000             // ignored
01001             if (consume_positional(argv[current])) {
01002             } else {
01003                 argv[nextKeep] = argv[current];
01004                 ++nextKeep;
01005             }
01006             // if we return from here then it was parsed successfully, so continue
01007         } else {
01008             // short or long option?
01009             if (result[4].length() != 0) {
01010                 const std::string &s = result[4];
01011 
01012                 for (std::size_t i = 0; i != s.size(); ++i) {
01013                     std::string name(1, s[i]);
01014                     auto iter = m_options.find(name);
01015 
01016                     if (iter == m_options.end()) {
01017                         if (m_allow_unrecognised) {
01018                             continue;
01019                         } else {
01020                             // error
01021                             throw option_not_exists_exception(name);
01022                         }
01023                     }
01024 
01025                     auto value = iter->second;
01026 
01027                     if (i + 1 == s.size()) {
01028                         // it must be the last argument
01029                         checked_parse_arg(argc, argv, current, value, name);
01030                     } else if (value->value().has_implicit()) {
01031                         parse_option(value, name, value->value().get_implicit_value());
01032                     } else {
01033                         // error
01034                         throw option_requires_argument_exception(name);
01035                     }
01036                 }
01037             } else if (result[1].length() != 0) {
01038                 const std::string &name = result[1];
01039 
01040                 auto iter = m_options.find(name);
01041 
01042                 if (iter == m_options.end()) {
01043                     if (m_allow_unrecognised) {
01044                         // keep unrecognised options in argument list, skip to next argument
01045                         argv[nextKeep] = argv[current];
01046                         ++nextKeep;
01047                         ++current;
01048                         continue;
01049                     } else {
01050                         // error
01051                         throw option_not_exists_exception(name);
01052                     }
01053                 }
01054 
01055                 auto opt = iter->second;
01056 
01057                 // equals provided for long option?
01058                 if (result[2].length() != 0) {
01059                     // parse the option given
01060 
01061                     parse_option(opt, name, result[3]);
01062                 } else {
01063                     // parse the next argument
01064                     checked_parse_arg(argc, argv, current, opt, name);
01065                 }
01066             }
01067         }
01068 
01069         ++current;
01070     }
01071 
01072     for (auto &opt : m_options) {
01073         auto &detail = opt.second;
01074         auto &value = detail->value();
01075 
01076         auto &store = m_results[detail];
01077 
01078         if (!store.count() && value.has_default()) {
01079             parse_default(detail);
01080         }
01081     }
01082 
01083     if (consume_remaining) {
01084         while (current < argc) {
01085             if (!consume_positional(argv[current])) {
01086                 break;
01087             }
01088             ++current;
01089         }
01090 
01091         // adjust argv for any that couldn't be swallowed
01092         while (current != argc) {
01093             argv[nextKeep] = argv[current];
01094             ++nextKeep;
01095             ++current;
01096         }
01097     }
01098 
01099     argc = nextKeep;
01100 }
01101 
01102 inline void Options::add_option(const std::string &group, const std::string &s, const std::string &l, std::string desc,
01103                                 std::shared_ptr<const Value> value, std::string arg_help) {
01104     auto stringDesc = toLocalString(std::move(desc));
01105     auto option = std::make_shared<OptionDetails>(s, l, stringDesc, value);
01106 
01107     if (s.size() > 0) {
01108         add_one_option(s, option);
01109     }
01110 
01111     if (l.size() > 0) {
01112         add_one_option(l, option);
01113     }
01114 
01115     // add the help details
01116     auto &options = m_help[group];
01117 
01118     options.options.emplace_back(HelpOptionDetails{s, l, stringDesc, value->has_default(), value->get_default_value(),
01119                                                    value->has_implicit(), value->get_implicit_value(), std::move(arg_help),
01120                                                    value->is_container(), value->is_boolean()});
01121 }
01122 
01123 inline void Options::add_one_option(const std::string &option, std::shared_ptr<OptionDetails> details) {
01124     auto in = m_options.emplace(option, details);
01125 
01126     if (!in.second) {
01127         throw option_exists_error(option);
01128     }
01129 }
01130 
01131 inline String Options::help_one_group(const std::string &g) const {
01132     typedef std::vector<std::pair<String, String>> OptionHelp;
01133 
01134     auto group = m_help.find(g);
01135     if (group == m_help.end()) {
01136         return "";
01137     }
01138 
01139     OptionHelp format;
01140 
01141     size_t longest = 0;
01142 
01143     String result;
01144 
01145     if (!g.empty()) {
01146         result += toLocalString(" " + g + " options:\n");
01147     }
01148 
01149     for (const auto &o : group->second.options) {
01150         if (o.is_container && m_positional_set.find(o.l) != m_positional_set.end() && !m_show_positional) {
01151             continue;
01152         }
01153 
01154         auto s = format_option(o);
01155         longest = std::max(longest, stringLength(s));
01156         format.push_back(std::make_pair(s, String()));
01157     }
01158 
01159     longest = std::min(longest, static_cast<size_t>(OPTION_LONGEST));
01160 
01161     // widest allowed description
01162     auto allowed = size_t{999} - longest - OPTION_DESC_GAP;
01163 
01164     auto fiter = format.begin();
01165     for (const auto &o : group->second.options) {
01166         if (o.is_container && m_positional_set.find(o.l) != m_positional_set.end() && !m_show_positional) {
01167             continue;
01168         }
01169 
01170         auto d = format_description(o, longest + OPTION_DESC_GAP, allowed);
01171 
01172         result += fiter->first;
01173         if (stringLength(fiter->first) > longest) {
01174             result += '\n';
01175             result += toLocalString(std::string(longest + OPTION_DESC_GAP, ' '));
01176         } else {
01177             result += toLocalString(std::string(longest + OPTION_DESC_GAP - stringLength(fiter->first), ' '));
01178         }
01179         result += d;
01180         result += '\n';
01181 
01182         ++fiter;
01183     }
01184 
01185     return result;
01186 }
01187 
01188 inline void Options::generate_group_help(String &result, const std::vector<std::string> &print_groups) const {
01189     for (size_t i = 0; i != print_groups.size(); ++i) {
01190         const String &group_help_text = help_one_group(print_groups[i]);
01191         if (empty(group_help_text)) {
01192             continue;
01193         }
01194         result += group_help_text;
01195         if (i < print_groups.size() - 1) {
01196             result += '\n';
01197         }
01198     }
01199 }
01200 
01201 inline void Options::generate_all_groups_help(String &result) const {
01202     std::vector<std::string> all_groups;
01203     all_groups.reserve(m_help.size());
01204 
01205     for (auto &group : m_help) {
01206         all_groups.push_back(group.first);
01207     }
01208 
01209     generate_group_help(result, all_groups);
01210 }
01211 
01212 inline std::string Options::help(const std::vector<std::string> &help_groups) const {
01213     String result = m_help_string + "\nUsage:\n  " + toLocalString(m_program) + " " + toLocalString(m_custom_help) +
01214                     "\n  Use equal sign to set boolean values (example: --dump_surfaces=true)";
01215 
01216     if (m_positional.size() > 0 && m_positional_help.size() > 0) {
01217         result += " " + toLocalString(m_positional_help);
01218     }
01219 
01220     result += "\n\n";
01221 
01222     if (help_groups.size() == 0) {
01223         generate_all_groups_help(result);
01224     } else {
01225         generate_group_help(result, help_groups);
01226     }
01227 
01228     return toUTF8String(result);
01229 }
01230 
01231 inline const std::vector<std::string> Options::groups() const {
01232     std::vector<std::string> g;
01233 
01234     std::transform(m_help.begin(), m_help.end(), std::back_inserter(g),
01235                    [](const std::map<std::string, HelpGroupDetails>::value_type &pair) { return pair.first; });
01236 
01237     return g;
01238 }
